import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Calculate the total amount for one line (qty × unitPrice, in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
/**
 * Calculate the due date based on payment terms and issue date.
 * @param {string} issueDate - date in YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} - due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Last day of the month of issueDate
    const [year, month] = issueDate.split('-').map(Number);
    const nextMonth = new Date(Date.UTC(year, month, 1));
    const lastDay = new Date(nextMonth.getTime() - 1000 * 60 * 60 * 24);
    const y = lastDay.getUTCFullYear();
    const m = String(lastDay.getUTCMonth() + 1).padStart(2, '0');
    const d = String(lastDay.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
}

export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate invoice totals (subtotal, discount, VAT, voucher, and total in cents).
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineDiscount = roundCents(lineTotal(line) * (line.discountPercent ?? 0) / 100);
    return sum + Math.max(0, lineDiscount);
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const lineTotal_ = lineTotal(line);
    const lineDiscount = roundCents(lineTotal_ * (line.discountPercent ?? 0) / 100);
    const lineAfterDiscount = Math.max(0, lineTotal_ - lineDiscount);
    const lineVat = roundCents(lineAfterDiscount * line.vatRate / 100);
    return sum + Math.max(0, lineVat);
  }, 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer exists
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return fail('TERMS_INVALID');
  }

  // Validate lines array is not empty
  if (!lines || lines.length === 0) return fail('NO_LINES');

  // Validate and build lines with product info
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent
    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;

    // Determine discount: explicit value takes precedence, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];

    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      ...(discountPercent > 0 && { discountPercent }),
    });
  }

  const dueDate = calculateDueDate(issueDate, terms);

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  };

  return ok(invoice);
}

/**
 * Add or update a line on a draft invoice.
 * If the SKU exists, increase its quantity; otherwise, add a new line.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent
  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  // Validate and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists on invoice
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      ...(discountPercent !== undefined && { discountPercent }),
    });
  }

  const updatedInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(updatedInvoice);
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line exists
  if (!invoice.lines.some((line) => line.sku === sku)) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  const updatedInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(updatedInvoice);
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, voucher?: any }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check for existing voucher
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  const updatedInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(updatedInvoice);
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - Array of already-used invoice numbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const issuedInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(issuedInvoice);
}

